  <title>Search Empty State · Copy Review</title>
  <style>
    :root {
      color-scheme: light;
      --ink: #29231f;
      --muted: #655d56;
      --line: #e6ddd5;
      --paper: #fcfaf7;
      --accent: #a3442e;
      --accent-soft: #f6e9e2;
      --lobe-color-primary: var(--accent);
    }

    * { box-sizing: border-box; }
    [hidden] { display: none !important; }
    body {
      margin: 0;
      background: var(--paper);
      color: var(--ink);
      font: 14px/1.5 system-ui, sans-serif;
    }

    .masthead { border-bottom: 1px solid var(--line); }
    .masthead-inner, main {
      width: min(1180px, calc(100% - 80px));
      margin-inline: auto;
    }
    .masthead-inner {
      display: flex;
      min-height: 63px;
      align-items: center;
      gap: 10px;
      font-weight: 700;
    }
    .masthead-mark {
      display: grid;
      width: 32px;
      height: 32px;
      place-items: center;
      background: var(--accent);
      color: white;
      border-radius: 9px;
    }
    .masthead-path {
      border-inline-start: 1px solid var(--line);
      padding-inline-start: 12px;
      margin-inline-start: 5px;
      color: var(--muted);
      font-weight: 500;
    }

    main { padding: 42px 0 48px; }
    h1, h2, h3, p, dl, dd { margin: 0; }
    h1, h2 {
      font-family: Georgia, serif;
      font-weight: 400;
      line-height: 1.08;
    }
    h1 {
      margin: 6px 0 12px;
      font-size: clamp(2.7rem, 5.2vw, 4.6rem);
      letter-spacing: -.062em;
    }
    h2 { font-size: 30px; letter-spacing: -.045em; }
    .intro { margin-bottom: 32px; }
    .eyebrow {
      font-size: 11px;
      font-weight: 750;
      letter-spacing: .13em;
      text-transform: uppercase;
      color: var(--accent);
    }
    .intro p:last-child { font-size: 15px; color: var(--muted); }
    .section-heading {
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 6px 18px;
      margin-bottom: 14px;
    }
    .section-heading p { color: var(--muted); font-size: 13px; }
    .options {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 16px;
      margin-bottom: 22px;
    }

    .option {
      display: block;
      min-width: 0;
      background: white;
      border: 1px solid var(--line);
      border-radius: 15px;
      box-shadow: 0 2px 4px #51261008;
    }
    .option[data-selected] {
      border-color: var(--accent);
      box-shadow: 0 0 0 1px var(--accent);
    }
    .option-heading {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 8px;
      min-height: 36px;
      margin-bottom: 12px;
    }
    .option-heading h3 { font-size: 15px; }
    .option-heading .eyebrow { margin-bottom: 2px; letter-spacing: .1em; }
    .product {
      border: 1px solid #e7e8ef;
      border-radius: 10px;
      overflow: hidden;
      color: #242a3a;
      background: #f8f9fc;
    }
    .product-bar {
      display: flex;
      align-items: center;
      gap: 8px;
      min-height: 43px;
      padding: 7px 12px;
      background: white;
      border-bottom: 1px solid #e7e8ef;
    }
    .product-logo { display: flex; color: #4a568b; }
    .product-query {
      display: flex;
      gap: 7px;
      align-items: center;
      min-width: 0;
      flex: 1;
      padding: 4px 8px;
      border: 1px solid #e7e8ef;
      border-radius: 6px;
      background: #f8f9fc;
      color: #444c64;
      font-size: 11px;
      line-height: 1.5;
    }
    .product-query span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    ryugi-icon { display: inline-flex; flex-shrink: 0; }
    .product-results {
      padding: 8px 12px;
      border-bottom: 1px solid #e7e8ef;
      color: #535b72;
      font-size: 11px;
      font-weight: 650;
    }
    .empty {
      display: grid;
      align-content: start;
      justify-items: center;
      gap: 6px;
      min-height: 174px;
      padding: 20px 12px 16px;
      text-align: center;
    }
    .empty-icon {
      display: grid;
      place-items: center;
      width: 45px;
      height: 45px;
      margin-bottom: 3px;
      border: 1px solid #dce1f1;
      border-radius: 13px;
      background: #eef0fa;
      color: #4a568b;
    }
    .empty-title { font-size: 15px; font-weight: 700; letter-spacing: -.025em; }
    .empty-description { max-width: 25ch; color: #535b72; font-size: 12px; }

    .review-control { margin-top: 15px; }
    .rating-heading, .rating-key {
      display: flex;
      justify-content: space-between;
      align-items: baseline;
      gap: 8px;
    }
    .rating-heading { margin-bottom: 6px; }
    .rating-heading p, .note-label { font-size: 13px; font-weight: 700; }
    .rating-key { margin-top: 5px; color: var(--muted); font-size: 11px; }
    .review-control ryugi-segmented, .pick { display: block; width: 100%; }
    .pick { margin-top: 13px; }

    .note {
      display: block;
      margin-bottom: 22px;
      background: white;
      border: 1px solid var(--line);
      border-radius: 15px;
    }
    .note-label { display: block; margin-bottom: 7px; }
    .note ryugi-textarea { display: block; width: 100%; }

    .summary {
      padding: 21px 22px 22px;
      border: 1px solid #e8d7cb;
      border-radius: 15px;
      background: #f5ebe3;
    }
    .summary h2 { margin-bottom: 15px; }
    .summary dl {
      display: grid;
      grid-template-columns: minmax(0, 1fr) minmax(0, 1.25fr) minmax(0, 1fr);
      gap: 14px 20px;
    }
    .summary dl > div { border-top: 1px solid #ddcabe; padding-top: 10px; min-width: 0; }
    .summary dt { font-size: 12px; font-weight: 750; }
    .summary dd { margin-top: 4px; color: var(--muted); font-size: 13px; overflow-wrap: anywhere; }
    #note-summary { white-space: pre-wrap; }
    .summary ul { padding: 0; margin: 0; list-style: none; }
    .summary li {
      display: flex;
      justify-content: space-between;
      gap: 8px;
      max-width: 240px;
    }
    .summary li + li { margin-top: 3px; }

    @media (max-width: 850px) {
      .masthead-inner, main { width: min(720px, calc(100% - 40px)); }
      .options { gap: 12px; }
      .option-heading { flex-wrap: wrap; }
      .empty { min-height: 205px; }
    }
    @media (max-width: 680px) {
      .masthead-inner, main { width: calc(100% - 32px); }
      main { padding-top: 30px; }
      .intro { margin-bottom: 24px; }
      .options, .summary dl { grid-template-columns: minmax(0, 1fr); }
      .empty { min-height: 153px; }
