</head>
<body>
  <header class="masthead">
    <div class="masthead-inner">
      <span class="masthead-mark" aria-hidden="true"><ryugi-icon name="file-text" size="16"></ryugi-icon></span>
      <span>Copy review</span>
      <span class="masthead-path">Search</span>
    </div>
  </header>

  <main id="review">
    <div class="intro">
      <p class="eyebrow">Search results</p>
      <h1>Empty state copy</h1>
      <p>Compare the three previews, rate each option’s tone, and choose the copy you’d use.</p>
    </div>

    <section aria-labelledby="options-heading">
      <div class="section-heading">
        <h2 id="options-heading">Copy options</h2>
        <p>Sample copy and search interface</p>
      </div>
      <div class="options">
        <ryugi-card id="option-a" class="option" variant="borderless">
          <div class="option-heading">
            <div><p class="eyebrow">Option A</p><h3>Direct</h3></div>
            <ryugi-tag id="selected-a" size="small" shape="round" color="#a3442e" hidden>Preferred</ryugi-tag>
          </div>
          <div class="product" role="group" aria-label="Option A search results preview">
            <div class="product-bar">
              <span class="product-logo" aria-hidden="true"><ryugi-icon name="layers" size="15"></ryugi-icon></span>
              <div class="product-query"><ryugi-icon name="search" size="12" aria-hidden="true"></ryugi-icon><span>Q4 planning</span></div>
            </div>
            <p class="product-results">Search results · 0 matches</p>
            <div class="empty">
              <div class="empty-icon" aria-hidden="true"><ryugi-icon name="search" size="21" stroke-width="1.65"></ryugi-icon></div>
              <p class="empty-title">No results found</p>
              <p class="empty-description">Try a different search term.</p>
            </div>
          </div>
          <div class="review-control">
            <div class="rating-heading"><p id="rating-label-a">Tone rating</p></div>
            <ryugi-segmented id="tone-a" size="small" block aria-label="Tone rating for option A" aria-describedby="rating-key-a">
              <ryugi-segment value="1">1</ryugi-segment><ryugi-segment value="2">2</ryugi-segment><ryugi-segment value="3">3</ryugi-segment><ryugi-segment value="4">4</ryugi-segment><ryugi-segment value="5">5</ryugi-segment>
            </ryugi-segmented>
            <div id="rating-key-a" class="rating-key"><span>1 · Poor fit</span><span>5 · Great fit</span></div>
          </div>
          <ryugi-button id="pick-a" class="pick" variant="outlined" block>Choose option A</ryugi-button>
        </ryugi-card>

        <ryugi-card id="option-b" class="option" variant="borderless">
          <div class="option-heading">
            <div><p class="eyebrow">Option B</p><h3>Conversational</h3></div>
            <ryugi-tag id="selected-b" size="small" shape="round" color="#a3442e" hidden>Preferred</ryugi-tag>
          </div>
          <div class="product" role="group" aria-label="Option B search results preview">
            <div class="product-bar">
              <span class="product-logo" aria-hidden="true"><ryugi-icon name="layers" size="15"></ryugi-icon></span>
              <div class="product-query"><ryugi-icon name="search" size="12" aria-hidden="true"></ryugi-icon><span>Q4 planning</span></div>
            </div>
            <p class="product-results">Search results · 0 matches</p>
            <div class="empty">
              <div class="empty-icon" aria-hidden="true"><ryugi-icon name="search" size="21" stroke-width="1.65"></ryugi-icon></div>
              <p class="empty-title">We couldn’t find a match</p>
              <p class="empty-description">Try a shorter phrase or a different keyword.</p>
            </div>
          </div>
          <div class="review-control">
            <div class="rating-heading"><p id="rating-label-b">Tone rating</p></div>
            <ryugi-segmented id="tone-b" size="small" block aria-label="Tone rating for option B" aria-describedby="rating-key-b">
              <ryugi-segment value="1">1</ryugi-segment><ryugi-segment value="2">2</ryugi-segment><ryugi-segment value="3">3</ryugi-segment><ryugi-segment value="4">4</ryugi-segment><ryugi-segment value="5">5</ryugi-segment>
            </ryugi-segmented>
            <div id="rating-key-b" class="rating-key"><span>1 · Poor fit</span><span>5 · Great fit</span></div>
          </div>
          <ryugi-button id="pick-b" class="pick" variant="outlined" block>Choose option B</ryugi-button>
        </ryugi-card>

        <ryugi-card id="option-c" class="option" variant="borderless">
          <div class="option-heading">
            <div><p class="eyebrow">Option C</p><h3>Guided</h3></div>
            <ryugi-tag id="selected-c" size="small" shape="round" color="#a3442e" hidden>Preferred</ryugi-tag>
          </div>
          <div class="product" role="group" aria-label="Option C search results preview">
            <div class="product-bar">
              <span class="product-logo" aria-hidden="true"><ryugi-icon name="layers" size="15"></ryugi-icon></span>
              <div class="product-query"><ryugi-icon name="search" size="12" aria-hidden="true"></ryugi-icon><span>Q4 planning</span></div>
            </div>
            <p class="product-results">Search results · 0 matches</p>
            <div class="empty">
              <div class="empty-icon" aria-hidden="true"><ryugi-icon name="search" size="21" stroke-width="1.65"></ryugi-icon></div>
              <p class="empty-title">No matches for “Q4 planning”</p>
              <p class="empty-description">Check the spelling or search for a broader term.</p>
            </div>
          </div>
          <div class="review-control">
            <div class="rating-heading"><p id="rating-label-c">Tone rating</p></div>
            <ryugi-segmented id="tone-c" size="small" block aria-label="Tone rating for option C" aria-describedby="rating-key-c">
              <ryugi-segment value="1">1</ryugi-segment><ryugi-segment value="2">2</ryugi-segment><ryugi-segment value="3">3</ryugi-segment><ryugi-segment value="4">4</ryugi-segment><ryugi-segment value="5">5</ryugi-segment>
            </ryugi-segmented>
            <div id="rating-key-c" class="rating-key"><span>1 · Poor fit</span><span>5 · Great fit</span></div>
          </div>
          <ryugi-button id="pick-c" class="pick" variant="outlined" block>Choose option C</ryugi-button>
        </ryugi-card>
      </div>
    </section>

    <section aria-labelledby="note-heading">
      <ryugi-card id="note-card" class="note" variant="borderless">
        <label id="note-heading" class="note-label" for="review-note">Review note</label>
        <ryugi-textarea id="review-note" rows="2" aria-label="Review note" placeholder="What worked, or what would you change?"></ryugi-textarea>
      </ryugi-card>
    </section>

    <section class="summary" id="summary" aria-labelledby="summary-heading">
      <h2 id="summary-heading">Review summary</h2>
      <dl>
        <div>
          <dt>Preferred copy</dt>
          <dd id="choice-summary" aria-live="polite">No option selected</dd>
        </div>
        <div>
          <dt>Tone ratings</dt>
          <dd>
            <ul aria-live="polite">
              <li><span>A · Direct</span><span id="score-a">Not rated</span></li>
              <li><span>B · Conversational</span><span id="score-b">Not rated</span></li>
              <li><span>C · Guided</span><span id="score-c">Not rated</span></li>
            </ul>
          </dd>
        </div>
        <div>
          <dt>Note</dt>
          <dd id="note-summary">No note yet</dd>
        </div>
      </dl>
    </section>
  </main>

  <script>
    document.addEventListener('"'ryugi-ui:ready', () => {
      const byId = (id) => document.getElementById(id);
      const options = ['a', 'b', 'c'].map((key) => ({
        key,
        card: byId('option-' + key),
        button: byId('pick-' + key),
        tag: byId('selected-' + key),
        rating: byId('tone-' + key),
        score: byId('score-' + key),
      }));
      const note = byId('review-note');
      const noteSummary = byId('note-summary');
      const choiceSummary = byId('choice-summary');

      function choose(option) {
        for (const candidate of options) {
          const selected = candidate === option;
          candidate.card.toggleAttribute('data-selected', selected);
          candidate.tag.hidden = "'!selected;
          candidate.button.setAttribute('"'aria-pressed', String(selected));
          candidate.button.setAttribute('variant', selected ? 'filled' : 'outlined');
        }
        const name = option.card.querySelector('h3').textContent;
        const title = option.card.querySelector('.empty-title').textContent;
        choiceSummary.textContent = 'Option ' + option.key.toUpperCase() + ' · ' + name + ' — ' + title;
      }

      for (const option of options) {
        const displayRating = (value) => {
          const rating = Number(value);
          option.score.textContent = Number.isInteger(rating) && rating >= 1 && rating <= 5
            ? rating + ' / 5'
            : 'Not rated';
        };
        option.button.setAttribute('aria-pressed', 'false');
        option.button.addEventListener('click', () => choose(option));
        option.rating.addEventListener('ryugi-change', (event) => displayRating(event.detail.value));
        displayRating(option.rating.value);
      }

      const displayNote = (value) => {
        noteSummary.textContent = value?.trim() || 'No note yet';
      };
      note.addEventListener('ryugi-change', (event) => displayNote(event.detail.value));
      displayNote(note.value);
    }, { once: true });
  </script>
</body>
</html>
EOF"

